function C.ChangeCursor(isLoading)
  if NgoEx._DEFAULT_CURSOR == nil then
    NgoEx._DEFAULT_CURSOR = Resources.Load("Texture2D", "Cursor/cursor")
  end
  if NgoEx._LOADING_CURSOR == nil then
    NgoEx._LOADING_CURSOR = Resources.Load("Texture2D", "Cursor/cursor_hourglass")
  end
  if isLoading then
    CursorManager:SetCursor(NgoEx._LOADING_CURSOR, Vector2.zero, "Auto")
  else
    CursorManager:SetCursor(NgoEx._DEFAULT_CURSOR, Vector2.zero, "Auto")
  end
end

function C.DenyCursor()
  if NgoEx._DENIED_CURSOR == nil then
    NgoEx._DENIED_CURSOR = Resources.Load("Texture2D", "Cursor/cursor_prohibition")
  end
  CursorManager:SetCursor(NgoEx._DENIED_CURSOR, Vector2.zero, "Auto")
end

function C.DelayNGO(milliseconds, token)
  if NgoEx._IS_DELAYING then
    return UniTask.NextFrame(token, false)
  end
  NgoEx._IS_DELAYING = true
  if NgoEx._DEFAULT_CURSOR == nil then
    NgoEx._DEFAULT_CURSOR = Resources.Load("Texture2D", "Cursor/cursor")
  end
  if NgoEx._LOADING_CURSOR == nil then
    NgoEx._LOADING_CURSOR = Resources.Load("Texture2D", "Cursor/cursor_hourglass")
  end
  return UniTask.Create(function()
    CursorManager:SetCursor(NgoEx._LOADING_CURSOR, Vector2.zero, "Auto")
    UniTask.Delay(milliseconds, false, "Update", token, false)
    CursorManager:SetCursor(NgoEx._DEFAULT_CURSOR, Vector2.zero, "Auto")
    NgoEx._IS_DELAYING = false
  end)
end

