function C.RandomizedElement(T, list)
  if list.Count < 1 then
    return list:FirstOrDefault()
  end
  local index = Random.Range(0, LCOUNT(list))
  return list:ElementAtOrDefault(index)
end

function C.GenerateRandomCharacters(length)
  local stringBuilder = NEW("StringBuilder", nil, length)
  local random = NEW("Random", nil)
  do
    local i = 0
    while i < length do
      local index = random:Next(STR.Length(NgoEx._RANDOM_CHARACTERS))
      local value = IDX(NgoEx._RANDOM_CHARACTERS, index)
      stringBuilder:Append(value)
      i = i + 1
    end
  end
  return TOSTR(stringBuilder)
end

return C
